pub(super) fn read_fields(fields: &mut BurnRebuildReceiptFields, entries: &[(Value, Value)]) {
    fields.exact_execution_observation_outcome_summary_replayed = bool_field(
        entries,
        "exact_execution_observation_outcome_summary_replayed",
    );
    fields.execution_observation_outcome_completed_count =
        int_field(entries, "execution_observation_outcome_completed_count");
    fields.execution_observation_outcome_failed_count =
        int_field(entries, "execution_observation_outcome_failed_count");
}

pub(super) fn accepted_claim(fields: &BurnRebuildReceiptFields) -> bool {
    let counts = fields
        .execution_observation_outcome_completed_count
        .zip(fields.execution_observation_outcome_failed_count);
    match fields.schema.as_deref() {
        Some(SCHEMA_V1) => {
            fields
                .exact_execution_observation_outcome_summary_replayed
                .is_none()
                && counts.is_none()
        }
        Some(SCHEMA) => match fields.exact_execution_observation_outcome_summary_replayed {
            Some(true) => counts.is_some(),
            Some(false) => counts.is_none(),
            None => false,
        },
        _ => false,
    }
}

pub(super) fn clear_fields(fields: &mut BurnRebuildReceiptFields) {
    fields.exact_execution_observation_outcome_summary_replayed = None;
    fields.execution_observation_outcome_completed_count = None;
    fields.execution_observation_outcome_failed_count = None;
}

fn bool_field(entries: &[(Value, Value)], field: &str) -> Option<bool> {
    match value_field(entries, field) {
        Some(Value::Bool(value)) => Some(*value),
        _ => None,
    }
}

fn int_field(entries: &[(Value, Value)], field: &str) -> Option<usize> {
    match value_field(entries, field) {
        Some(Value::Int(value)) => (*value).try_into().ok(),
        _ => None,
    }
}

